function startWidgetConversation() { chatWorkspace.value?.newConversation(); }
watch(() => route.path, () => { chatOpen.value = false; });
onMounted(async () => {
  try {
    products.value = await fetchProducts();
  } catch {
    products.value = [];
  }
});
